/** Why the composer is replaced (C20 / SPEC 13d): null while the member may send. */
export const CANT_SEND_REASONS = ["blocked_by_me", "blocked", "closed", "muted", "left"] as const;
export type CantSendReason = (typeof CANT_SEND_REASONS)[number];

/** The composer lines for each reason (C20, SPEC 13d §3.15). `muted` takes the end of the mute. */
export function cantSendText(reason: CantSendReason, mutedUntil?: string | null): string {
  switch (reason) {
    case "blocked_by_me":
      return "You blocked this member.";
    case "blocked":
    case "left":
      return "You can't message this member.";
    case "closed":
      return "This member left Phriend. You can still read the conversation.";
    case "muted":
      return mutedUntil ? `You are muted until ${mutedText(mutedUntil)} because of offensive language. You can still read messages.` : "You are muted because of offensive language. You can still read messages.";
  }
}

