export const SEND_REFUSALS = ["muted", "blocked", "closed", "moderated", "rate_limited"] as const;

/** The inbox's one-line preview of a message. */
export function previewOf(m: Pick<Message, "kind" | "body" | "state" | "meta">): string {
  if (m.state === "removed") return "Message removed";
  if (m.state === "deleted") return "Message deleted";
  switch (m.kind) {
    case "image":
      return m.body ? m.body : "Photo";
    case "booking":
      return "Booking update";
    case "payment_details":
      return "Payment details";
    case "system":
      return m.meta?.context ? `About: ${m.meta.context.title}` : "";
    default:
      return m.body ?? "";
  }
}

// ---- the typed client ----

export function chatApi(api: Client) {
  const c = (id: string) => `/v1/conversations/${encodeURIComponent(id)}`;
  return {
    inbox: (q: { archived?: boolean; cursor?: string | null; limit?: number } = {}): Promise<ApiResult<InboxPage>> =>
      api.get("/v1/conversations", { query: { archived: q.archived ? "true" : undefined, cursor: q.cursor ?? undefined, limit: q.limit }, schema: inboxPageSchema }),
    /** Client: get or create the conversation with a seller (from a service: pass its id as the context). */
    open: (body: OpenConversationBody): Promise<ApiResult<ConversationHeader>> => api.post("/v1/conversations", body, { schema: conversationHeaderSchema }),
    header: (id: string): Promise<ApiResult<ConversationHeader>> => api.get(c(id), { schema: conversationHeaderSchema }),
    /** Newest first. `before`: older pages; `after`: what came since (a reconnect). */
    messages: (id: string, q: HistoryQuery = {}): Promise<ApiResult<MessagePage>> => api.get(`${c(id)}/messages`, { query: { before: q.before, after: q.after, limit: q.limit }, schema: messagePageSchema }),
    send: (id: string, body: SendMessageBody): Promise<ApiResult<Message>> => api.post(`${c(id)}/messages`, body, { schema: messageSchema }),
    remove: (id: string, messageId: string): Promise<ApiResult<Message>> => api.delete(`${c(id)}/messages/${encodeURIComponent(messageId)}`, { schema: messageSchema }),
    react: (id: string, messageId: string, emoji: Reaction | null): Promise<ApiResult<ReactionsEvent>> => api.put(`${c(id)}/messages/${encodeURIComponent(messageId)}/reaction`, { emoji }, { schema: reactionsSchema }),
    markRead: (id: string, messageId: string): Promise<ApiResult<ReadResult>> => api.post(`${c(id)}/read`, { messageId }, { schema: readResultSchema }),
    membership: (id: string, body: MembershipBody): Promise<ApiResult<InboxRow>> => api.patch(`${c(id)}/membership`, body, { schema: inboxRowSchema }),
    askFaq: (id: string, faqItemId: string): Promise<ApiResult<FaqAnswerResult>> => api.post(`${c(id)}/faq-answers`, { faqItemId }, { schema: faqAnswerResultSchema }),
    sendPaymentDetails: (id: string, paymentMethodId: string): Promise<ApiResult<Message>> => api.post(`${c(id)}/payment-details`, { paymentMethodId }, { schema: messageSchema }),
    /** a provider's proposal (`Idempotency-Key`: one per proposal sheet, reused for its retries) */
    propose: (id: string, body: ProposalBody, idempotencyKey: string): Promise<ApiResult<ProposalResult>> => api.post(`${c(id)}/proposals`, body, { idempotencyKey, schema: proposalResultSchema }),
  };
}
export type ChatApi = ReturnType<typeof chatApi>;
